// Content localisation for Drive&Deal only. The protected demo is excluded.
(() => {
  const data = {"copy":{"ru":{"hero_eyebrow":"01 / Избранный кейс · 2026","hero_title":"Автосалон <span style=\"color:var(--accent)\">Drive&amp;Deal.</span>","hero_lead":"От выбора автомобиля до заявки и её обработки — приложение для iPhone.","hero_note":"Исследование, UX/UI и работающий iOS-прототип. Приложение самостоятельно спроектировано и реализовано с помощью Codex.","hero_tag_0":"UX-исследование","hero_tag_1":"Продуктовый дизайн","hero_tag_2":"iOS","hero_tag_3":"CRM","hero_cta":"Исследовать проект <span class=\"dd-cta-arrow\" aria-hidden=\"true\">↘</span>","eyebrow_1":"02 / Контекст и задача","s02_00":"Drive&amp;Deal. Автосалон в iPhone, спроектированный с нуля.","s02_01":"Drive&amp;Deal вырос из самостоятельной продуктовой инициативы. На старте не было ни готового ТЗ, ни заданного сценария. Задача была сформулирована с нуля: помочь человеку выбрать автомобиль, записаться на тест-драйв или оставить заявку на покупку, а дилеру — продолжить общение с клиентом до визита.","s02_02":"Клиент знакомится с моделями, сравнивает комплектации и отправляет заявку с одного экрана с прокруткой. Приложение подтверждает отправку, показывает статус и подсказывает, что произойдёт дальше. Менеджер получает заявку в CRM, связывается с клиентом, уточняет детали, согласовывает визит и обновляет статус. К визиту менеджер готовит выбранный автомобиль или информацию о комплектации и условиях покупки. В салоне он встречает клиента и проводит тест-драйв или обсуждает покупку в зависимости от заявки.","s02_03":"Весь цикл — самостоятельная работа: от постановки задачи и исследования до рабочего приложения для iPhone.","s02_04":"<strong>Платформа:</strong> iPhone.","s02_05":"<strong>Инструменты:</strong> Figma, Swift, Xcode, Codex.","s02_06":"<strong>Фокус MVP:</strong> каталог, карточка автомобиля, комплектации, оформление и обработка заявок.","s02_07":"Три задачи, которые связали интерфейс","s02_08":"<li><strong>Сравнить перед решением.</strong> Фотографии, цены и характеристики комплектаций должны помогать выбрать автомобиль.</li><li><strong>Оформить без лишнего ввода.</strong> Количество обязательных полей, переходы и заметность кнопок влияют на заполнение заявок.</li><li><strong>Понимать состояние заявки.</strong> После отправки нужны подтверждение, статус и понятное продолжение общения с дилером.</li>","eyebrow_2":"03 / Исследование","s03_00":"Где пользователь теряет уверенность.","s03_01":"Проведены три глубинных интервью с респондентами: 15 вопросов в семи тематических блоках. Изучены выбор автомобиля, заполнение заявки и ожидания от контакта с менеджером.<br>По материалам интервью оформлены две персоны и карта пути клиента (CJM) из семи этапов.","s03_02":"Главное из исследования","s03_03":"<strong>Кнопки действия нужно быстрее находить.</strong> Пользователи ожидали заметного перехода к покупке или тест-драйву. На карточке автомобиля усилена визуальная иерархия этих действий.","s03_04":"<strong>Три поля ввода воспринимаются как лишняя работа.</strong> Фамилия, имя и отчество объединены в одно поле. В финальной форме для связи нужен номер телефона, который можно проверить и изменить перед отправкой.","s03_05":"<strong>Прогресс-бар помогает оценить оставшийся объём.</strong> В раннем прототипе добавлен индикатор заполнения заявки «прогресс-бар», чтобы человек понимал, на каком этапе заполнения находится и сколько этапов ещё осталось. В финальной форме ориентироваться помогают пронумерованные группы полей на одном экране с прокруткой.","s03_06":"<strong>Форму можно пройти на одном экране.</strong> На проверке прототипа респонденты предложили объединить поля заявки и отдельный экран комментария в один экран с прокруткой. В финальной версии можно вернуться к любому полю и отправить заявку с того же экрана.","s03_07":"<strong>Выбор времени важен до звонка менеджера.</strong> Для тест-драйва дата и время выбираются прямо в форме.","s03_08":"<strong>Подтверждение должно объяснять продолжение.</strong> Пользователю нужны сведения о выбранном автомобиле, состоянии обращения, индикация успешной отправки заявки и информация о следующем действии.","s03_09":"CJM: от интереса к подтверждению","s03_11":"На этапе проверки контактов клиенту важно видеть, какие данные подставлены из профиля, и иметь возможность их исправить. После отправки нужны две разные вещи: подтверждение, что заявка принята, и ясность о следующем шаге. Менеджер видит новую заявку в CRM и связывается с клиентом, чтобы подтвердить визит.","s03_12":"Проработаны три ситуации, в которых клиент может подать заявку на покупку автомобиля или тест-драйв: в спокойной обстановке, на улице и в спешке при слабой связи. В обоих сценариях нужно выбрать автомобиль и дилера, проверить контакты и получить подтверждение. Для тест-драйва также выбираются дата и время.","cjm_alt":"Карта пути пользователя с задачами, затруднениями и возможностями улучшения оформления заявки.","cjm":"Исходная карта пути из исследования. На ней зафиксированы ранние гипотезы, включая прогресс-бар для пошагового прототипа.","eyebrow_3":"04 / Гипотезы и приоритеты","s04_00":"Сначала — изменения в основном пути заявки.","s04_01":"В интервью и на карте пути выделились три препятствия: трудно найти нужную кнопку, форма требует лишнего ввода, а после отправки непонятно, дошла ли заявка. Для первой рабочей версии (MVP) поставлена цель собрать полный путь: от выбора автомобиля до заявки, с которой менеджер может начать работу.","s04_02":"<thead><tr><th scope=\"col\">Требование</th><th scope=\"col\">MoSCoW</th><th scope=\"col\">Impact</th><th scope=\"col\">Effort</th><th scope=\"col\">Value</th><th scope=\"col\">Балл</th></tr></thead><tbody><tr><th scope=\"row\">Контрастные кнопки покупки и записи</th><td>Must</td><td>5</td><td>1</td><td>5</td><td>9</td></tr><tr><th scope=\"row\">Единое поле ФИО</th><td>Must</td><td>4</td><td>1</td><td>4</td><td>7</td></tr><tr><th scope=\"row\">Прогресс-бар в раннем прототипе</th><td>Must</td><td>4</td><td>2</td><td>4</td><td>6</td></tr><tr><th scope=\"row\">Самостоятельный выбор даты и времени</th><td>Must</td><td>5</td><td>3</td><td>5</td><td>7</td></tr><tr><th scope=\"row\">Форма без поля email</th><td>Should</td><td>3</td><td>1</td><td>3</td><td>5</td></tr><tr><th scope=\"row\">Уведомление менеджера в CRM</th><td>Must</td><td>4</td><td>3</td><td>5</td><td>6</td></tr><tr><th scope=\"row\">Дашборд заявок</th><td>Should</td><td>3</td><td>4</td><td>4</td><td>3</td></tr><tr><th scope=\"row\">Набор компонентов в Figma</th><td>Must</td><td>4</td><td>2</td><td>3</td><td>5</td></tr><tr><th scope=\"row\">Обработка ошибок сети</th><td>Should</td><td>4</td><td>3</td><td>4</td><td>5</td></tr><tr><th scope=\"row\">Сохранение черновика заявки</th><td>Should</td><td>3</td><td>3</td><td>3</td><td>3</td></tr></tbody>","eyebrow_4":"05 / Проектирование","s05_00":"Три способа организовать запись.","wireframes_alt":"Ранние схемы главной, вариантов каталога, карточки модели и комплектаций.","wireframes":"Вайрфреймы — упрощённые схемы будущего интерфейса приложения, показывающие структуру каталога и путь к выбору автомобиля.","eyebrow_5":"06 / Интерфейс приложения","s06_00":"От каталога к конкретному автомобилю.","app_0_alt":"Главный экран Drive&Deal: поиск и популярные модели.","app_0":"01 — Главная и популярные модели.","s06_01":"<strong>Каталог и поиск.</strong> Популярные модели на главной и отдельный модельный ряд позволяют перейти к автомобилю и найти нужную модель.","app_1_alt":"Карточка Hyundai ELANTRA с фотографиями, преимуществами и кнопками покупки и тест-драйва.","app_1":"02 — Карточка автомобиля и действия.","s06_02":"<strong>Карточка автомобиля.</strong> Фотографии, преимущества, комплектации и действия собраны вокруг выбранной модели. Покупка и запись на тест-драйв различаются подписью и оформлением.","app_2_alt":"Таблица сравнения комплектаций Hyundai ELANTRA по цене, характеристикам и оснащению.","app_2":"03 — Сравнение комплектаций.","s06_03":"<strong>Сравнение комплектаций.</strong> Цена, двигатель, трансмиссия и оснащение сопоставляются в одной таблице. Можно оценить различия перед обращением к дилеру.","app_3_alt":"Форма тест-драйва с автомобилем, комплектацией, дилером, датой, временем и контактами.","app_3":"04 — Финальная форма записи на тест-драйв.","s06_04":"<strong>Оформление обращения.</strong> В финальной форме автомобиль, комплектация, город, дилер и контакты находятся на одном экране с прокруткой. Для тест-драйва добавляются дата и время. ФИО и телефон подставляются из профиля, их можно изменить перед отправкой.","s06_07":"Посмотреть клиентский сценарий ↗","eyebrow_6":"07 / Работа с заявкой","s07_00":"Две стороны одного обращения.","s07_01":"Клиент выбирает автомобиль, отправляет заявку и следит за её статусом. Менеджер получает данные в CRM и помогает перейти от заявки к визиту в салон.","s07_02":"<li><span class=\"dd-flow-index\">01</span><span>Выбор автомобиля</span></li><li><span class=\"dd-flow-index\">02</span><span>Отправка заявки</span></li><li><span class=\"dd-flow-index\">03</span><span>Обработка менеджером</span></li><li><span class=\"dd-flow-index\">04</span><span>Просмотр статуса клиентом</span></li>","s07_03":"Для клиента: заявки и статусы","s07_04":"В профиле и разделе заявок доступны обращения на покупку и тест-драйв. В подробностях — автомобиль, комплектация, дилер, контакты и текущий статус. Заявку можно отменить.","role_0_alt":"Клиентский список заявок на тест-драйв и покупку со статусами в тёмной теме.","role_0":"Клиент — список заявок.","s07_05":"Посмотреть клиентский сценарий ↗","s07_06":"Для менеджера: обработка заявок","s07_07":"В CRM-панели обращения разделены на покупку и тест-драйв. Карточка содержит данные клиента и автомобиля, статус, кнопки звонка, WhatsApp и Telegram.","role_1_alt":"CRM-панель с данными клиента и автомобиля, статусами и кнопками связи.","role_1":"Менеджер — CRM-панель.","s07_08":"Посмотреть работу CRM ↗","maps_alt":"Подробности заявки на покупку с адресом дилера, контактами и отменой.","maps":"Подробности заявки и адрес дилера.","s07_09":"Следующее действие — маршрут к дилеру","s07_10":"Адрес доступен в подробностях заявки. Переход к картам позволяет построить маршрут без ручного копирования адреса: предусмотрен выбор Apple Maps, Яндекс Карт или 2ГИС.","s07_11":"Посмотреть переход к картам ↗","eyebrow_7":"08 / Дизайн-система","s08_00":"Компоненты, состояния и две темы.","s08_01":"Для светлой и тёмной тем описаны типографика, сетка, цвета и компоненты. Отдельно зафиксированы поведение элементов и требования к переходам между экранами.","s08_02":"<strong>Типографика.</strong> SF Pro Display и SF Pro Text; иерархия от названия модели и цены до характеристик и вспомогательных подписей.","s08_03":"<strong>Компоненты.</strong> Карточки автомобилей и комплектаций, кнопки действий, поля формы, навигация, статусы и подтверждения.","s08_04":"<strong>Состояния.</strong> Обычное, нажатие, недоступность, ошибка и успех. Цвет и текст помогают различать состояние элемента или обращения.","s08_05":"<strong>Две темы.</strong> Светлая и тёмная палитры с согласованной иерархией текста, поверхностей и акцентов.","s08_06":"В документации зафиксированы критерии приёмки для переходов из карточки модели, отображения комплектаций, прокрутки, поведения на узком экране и проверки контраста.","system_alt":"Дизайн-система Drive&Deal с типографикой, палитрами, сеткой и состояниями элементов.","system":"Светлая и тёмная темы, компоненты и состояния.","eyebrow_8":"09 / Пользовательская проверка","s09_00":"От трёх экранов к одной форме.","s09_01":"Проектирование начато с вопроса о многошаговой форме: поможет ли индикатор понять, сколько осталось до отправки? Сравнение двух прототипов дало ответ и подсказало, как сократить сам путь заявки.","test_0_alt":"Вариант A: контакты, комментарий и подтверждение без индикатора прогресса.","test_0":"Вариант A · прототип без индикатора.","test_1_alt":"Вариант B: те же три экрана с индикаторами 1/3, 2/3 и 3/3 в правом верхнем углу.","test_1":"Вариант B · промежуточный прототип с индикатором.","s09_02":"<thead><tr><th scope=\"col\">Показатель</th><th scope=\"col\">Без индикатора</th><th scope=\"col\">С индикатором</th><th scope=\"col\">Финальная форма · цель</th></tr></thead><tbody><tr><th scope=\"row\">Среднее время выполнения</th><td>52 с</td><td>47,4 с</td><td>≤ 40 с</td></tr><tr><th scope=\"row\">Среднее количество ошибок</th><td>0,4</td><td>0</td><td>0</td></tr><tr><th scope=\"row\">Среднее количество повторных действий</th><td>0,6</td><td>0</td><td>0</td></tr><tr><th scope=\"row\">Понятность процесса</th><td>3,8 / 5</td><td>5 / 5</td><td>5 / 5</td></tr><tr><th scope=\"row\">Уверенность в завершении</th><td>3,4 / 5</td><td>5 / 5</td><td>5 / 5</td></tr></tbody>","s09_03":"Обе группы дошли до подтверждения. С индикатором участники справлялись в среднем на 4,6 секунды быстрее, а ошибок и повторных действий в этой группе не зафиксировано. Это помогло понять, что клиенту важно видеть структуру формы.","s09_04":"В среднем для клиента с заполненным профилем. Это примерно на <strong>16% меньше</strong> замера варианта B. Для ошибок, повторных действий, понятности и уверенности цель — сохранить уровень варианта B.","s09_05":"Формулировки: объяснить действие до нажатия","s09_06":"Формулировки отдельно проверены с четырьмя участниками. В многошаговом прототипе «Продолжить» обозначало переход к следующему экрану. В финальной форме основная кнопка называет действие, которое произойдёт после нажатия: отправка заявки на покупку или запись на тест-драйв.","s09_07":"После отправки анимация подтверждает успех. На экране видны автомобиль и комплектация, для которых оформлена заявка. Для тест-драйва следующим шагом остаётся звонок менеджера для подтверждения визита.","eyebrow_9":"10 / Результаты и выводы","s10_00":"От исследования до работающего приложения.","s10_01":"Проект прошёл путь от интервью, карты пути клиента и вайрфреймов до интерфейсов и рабочего приложения для iPhone. С помощью Codex реализованы каталог, карточка автомобиля, сравнение комплектаций, формы покупки и тест-драйва, раздел заявок, CRM-панель и переход к картам.","s10_02":"Показатели промежуточного спринта","result_0":"45 → 20 с","result_detail_0":"сокращение примерно на 55%","result_label_0":"Время заполнения формы","result_1":"40% → 18%","result_detail_1":"снижение на 22 п. п.","result_label_1":"Отвал на третьем шаге","result_2":"+28%","result_detail_2":"к базовому значению","result_label_2":"Конверсия в заявки","result_3":"+45%","result_detail_3":"к базовому значению","result_label_3":"Клики по «Купить»","s10_04":"Что изменилось в продукте","s10_05":"Финальная форма собирает заявку на одном экране с прокруткой. Клиент выбирает город и дилера, проверяет предзаполненные ФИО и телефон и при необходимости редактирует их. Для тест-драйва на этом же экране можно выбрать дату и время.","s10_06":"Реализация позволила проверить эти решения в связанной последовательности: выбрать автомобиль, оформить обращение, открыть его со стороны клиента и перейти к обработке в CRM-панели.","s10_07":"Следующая итерация","s10_08":"На следующей проверке финальной формы предстоит сравнить время заполнения, ошибки и повторные действия на сопоставимых заданиях. Также предстоит проверить оформление заявки за другого человека и сохранение данных при слабой связи.","system_board":"<div class=\"dd-system-top\"><div><span class=\"dd-system-kicker\">Основы интерфейса</span><h3>Одна система. Две темы.</h3></div><div class=\"dd-theme-switch\" role=\"group\" aria-label=\"Тема примеров\"><button type=\"button\" data-dd-theme=\"light\" aria-pressed=\"true\">Светлая</button><button type=\"button\" data-dd-theme=\"dark\" aria-pressed=\"false\">Тёмная</button></div></div>\n <h4>Палитра</h4><ul class=\"dd-palette\"><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-primary)\"></span><strong>Основной акцент</strong><code><span class=\"dd-token-light\">#002C5F</span><span class=\"dd-token-dark\">#263F72</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-secondary)\"></span><strong>Вторичный акцент</strong><code><span class=\"dd-token-light\">#007FA8</span><span class=\"dd-token-dark\">#4DD9FF</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-text)\"></span><strong>Основной текст</strong><code><span class=\"dd-token-light\">#1A1A1A</span><span class=\"dd-token-dark\">#FFFFFF</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-muted)\"></span><strong>Вторичный текст</strong><code><span class=\"dd-token-light\">#666666</span><span class=\"dd-token-dark\">#8E8E93</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-background)\"></span><strong>Фон</strong><code><span class=\"dd-token-light\">#F5F6F8</span><span class=\"dd-token-dark\">#000000</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-border)\"></span><strong>Граница</strong><code><span class=\"dd-token-light\">#E0E0E0</span><span class=\"dd-token-dark\">#404047</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-success)\"></span><strong>Успех</strong><code><span class=\"dd-token-light\">#4CAF50</span><span class=\"dd-token-dark\">#4CAF50</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-error)\"></span><strong>Ошибка</strong><code><span class=\"dd-token-light\">#F44336</span><span class=\"dd-token-dark\">#F44336</span></code></li></ul>\n <div class=\"dd-system-details\"><section class=\"dd-type-section\"><h4>Типографика</h4><p>SF Pro Display · SF Pro Text</p><ul class=\"dd-type-list\"><li><span class=\"dd-type-meta\">28 · 700</span><span style=\"font-size:28px;font-weight:700\">Hyundai ELANTRA</span><small>Название модели</small></li><li><span class=\"dd-type-meta\">22 · 700</span><span style=\"font-size:22px;font-weight:700\">Цена автомобиля</span><small>Цена</small></li><li><span class=\"dd-type-meta\">18 · 600</span><span style=\"font-size:18px;font-weight:600\">Комплектации и цены</span><small>Заголовок раздела</small></li><li><span class=\"dd-type-meta\">15 · 400</span><span style=\"font-size:15px;font-weight:400\">Выберите удобные дату и время.</span><small>Основной текст</small></li><li><span class=\"dd-type-meta\">13 · 400</span><span style=\"font-size:13px;font-weight:400\">Дополнительная информация</span><small>Подпись</small></li></ul></section><section><h4>Ритм и отступы</h4><p>Базовая шкала отступов</p><ul class=\"dd-spacing\"><li><span style=\"width:12px\"></span><code>4</code></li><li><span style=\"width:24px\"></span><code>8</code></li><li><span style=\"width:48px\"></span><code>16</code></li><li><span style=\"width:72px\"></span><code>24</code></li><li><span style=\"width:96px\"></span><code>32</code></li></ul><div class=\"dd-spacing-notes\"><span>16 px — поля экрана</span><span>24 px — между блоками</span></div><h4>Переходы</h4><dl class=\"dd-motion-list\"><div><dt>Новый экран</dt><dd>300 ms</dd></div><div><dt>Галерея</dt><dd>800 ms</dd></div><div><dt>Прогресс-бар · ранний прототип</dt><dd>400 ms</dd></div></dl></section></div>\n <section class=\"dd-component-section\"><h4>Компоненты и состояния</h4><div class=\"dd-component-grid\"><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Основное действие</span><button type=\"button\" class=\"dd-sample-button\" data-dd-sample>Купить</button><small>Наведите и нажмите</small></div><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Недоступное действие</span><button type=\"button\" class=\"dd-sample-button\" disabled>Продолжить</button><small>Состояние Disabled</small></div><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Обратная связь</span><span class=\"dd-sample-feedback\">✓ Заявка отправлена</span><span class=\"dd-sample-error\">Проверьте номер телефона</span></div></div></section>","customer_kicker":"Клиентский опыт","customer_title":"Путь клиента: от выбора до визита.","customer_intro":"Каталог, сравнение, покупка и тест-драйв складываются в связный путь. После отправки заявки человек остаётся в контексте: видит статус обращения и может перейти к маршруту до дилера.","full_title":"Всё приложение: полный путь клиента","full_description":"Полная демонстрация приложения — от знакомства с моделями и сравнения комплектаций до оформления обращения и работы с заявками. В одном ролике показаны возможности продукта и переходы между его разделами.","full_meta":"Полный обзор приложения","purchase_title":"Покупка: от выбора к заявке","purchase_description":"В финальной форме клиент выбирает автомобиль, комплектацию, город и дилера, проверяет контакты из профиля и отправляет заявку с того же экрана. Экран подтверждения показывает автомобиль и комплектацию.","test_drive_title":"Тест-драйв: от интереса к записи","test_drive_description":"Запись использует ту же форму, с выбором даты и времени визита. Клиент может поправить ФИО и телефон перед отправкой. После неё приложение сообщает, что менеджер свяжется для подтверждения тест-драйва.","status_title":"Заявки и статусы: продолжение после отправки","status_description":"Раздел заявок возвращает человеку контроль над обращением. Здесь собраны заявки на покупку и тест-драйв; в подробностях доступны автомобиль, комплектация, дилер, контакты и текущий статус. При изменении планов заявку можно отменить.","route_title":"Маршрут к дилеру: следующий шаг к встрече","route_description":"Адрес дилера доступен прямо в заявке. Его можно открыть в Apple Maps, Яндекс Картах или 2ГИС и построить маршрут без ручного копирования адреса — перейти от цифрового обращения к визиту.","employee_kicker":"Работа сотрудника","employee_title":"Рабочее место менеджера. От заявки до визита.","employee_intro":"В CRM видно, кто обратился, какой автомобиль выбрал и с какой целью планирует визит. Менеджер связывается с клиентом, согласовывает визит и обновляет статус. К встрече он готовит автомобиль для тест-драйва или предложение по покупке.","manager_title":"Обработка заявок в CRM","manager_description":"Заявки на покупку и тест-драйв разделены по типу обращения. В карточке менеджер видит клиента, автомобиль, комплектацию и статус, а затем может позвонить или перейти в WhatsApp и Telegram. Контекст и следующее действие находятся рядом.","cjm_conclusion":"<strong>Вывод.</strong> Выбор дилера и времени, контакты и комментарий собраны на одном экране с прокруткой. Подтверждение завершает оформление, а статус в разделе заявок показывает, что происходит дальше.","context_title":"Контекст использования","context_conditions":"Условия","context_risk":"Возможные ошибки и сбои","context_response":"Требования к интерфейсу","context_quiet_title":"Спокойная обстановка","context_quiet_level":"Низкая нагрузка","context_quiet_conditions":"Тихий офис, стабильный Wi-Fi, обе руки свободны.","context_quiet_risk":"Даже без спешки можно допустить опечатку в номере или выбрать не ту дату. В спокойной обстановке проще заметить и исправить ошибку до отправки.","context_quiet_response":"Понятный порядок полей, доступные условия согласия и возможность проверить данные перед отправкой.","context_street_title":"На улице","context_street_level":"Средняя нагрузка","context_street_conditions":"Шум, яркий свет и отвлечения. Одна рука занята.","context_street_risk":"Из-за бликов и отвлечений легко ошибиться в номере, пропустить поле согласия или потерять нужный раздел при прокрутке.","context_street_response":"Крупные контрастные кнопки и заметный чекбокс. Понятные группы полей, подсказка формата номера и ошибки рядом с полями.","context_rush_title":"В спешке и при слабой сети","context_rush_level":"Высокая нагрузка","context_rush_conditions":"Мало времени, плохая видимость и нестабильная связь 2G/3G.","context_rush_risk":"Форма может не загрузиться, а отправка может прерваться. Если результата не видно, клиент может нажать «Отправить» повторно и создать дубликат заявки.","context_rush_response":"Минимум обязательных полей. Показать загрузку, сохранить введённые данные при сбое и дать повторить отправку без дублей. Подтвердить, когда заявка получена.","cjm_intro":"Карта пути клиента (CJM) показывает запись на тест-драйв от выбора модели до визита.<br>В колонке «Ответ интерфейса» описана финальная версия. Цветом выделены два этапа,<br>на которых клиенту особенно нужна ясность: проверка контактов и отправка.","context_comparison":"<strong>Что показало сравнение.</strong> В спокойной обстановке проще перепроверить данные перед отправкой. На улице сложнее заметить поле или подсказку. При слабой связи даже правильно заполненная заявка может не дойти до дилера. Поэтому форма должна помогать и при заполнении, и после нажатия «Отправить».","context_conclusion":"<strong>Вывод.</strong> В форме стоит оставить только необходимые поля, показывать ошибки рядом с ними и ясно сообщать, когда заявка отправляется и когда дилер её получил. Если связь прервалась, клиенту нужно дать возможность повторить отправку с теми же данными без создания второй заявки.","priority_hypotheses_title":"Что стоило проверить","priority_hypotheses_intro":"По итогам интервью сформулированы пять основных гипотез. Для каждой описано, что меняется, как сравнить варианты и по какому критерию оценить результат.","priority_check":"Как планировалась проверка","priority_target":"Критерий успеха","priority_h1_title":"Заметные кнопки покупки и тест-драйва","priority_h1_reason":"Клиенты хотели быстрее находить нужное действие на карточке автомобиля.","priority_h1_check":"Сравнить прежний вариант карточки с новой иерархией двух кнопок.","priority_h1_target":"Рост числа кликов по «Купить» не менее чем на 15%.","priority_h2_title":"Одно поле для ФИО","priority_h2_reason":"Три поля для имени заставляли клиентов тратить больше времени на ввод.","priority_h2_check":"Сравнить время заполнения формы с тремя полями и с одним.","priority_h2_target":"Сокращение времени заполнения не менее чем на 30%.","priority_h3_title":"Выбор даты и времени тест-драйва","priority_h3_reason":"Клиенты хотели видеть доступное время и записываться без отдельного звонка.","priority_h3_check":"Сравнить форму с выбором свободного времени и прежний вариант.","priority_h3_target":"Рост числа завершённых заявок не менее чем на 20%.","priority_h4_title":"Прогресс-бар в раннем прототипе","priority_h4_reason":"Клиенты сомневались, сколько ещё займёт заполнение формы.","priority_h4_check":"Сравнить прохождение одного сценария в двух версиях прототипа: с индикатором и без него.","priority_h4_target":"Снижение числа незавершённых форм не менее чем на 20%.","priority_h5_title":"Контакт по телефону без поля email","priority_h5_reason":"В интервью телефон называли основным способом связи с дилером.","priority_h5_check":"Сравнить долю отправленных заявок среди начавших заполнение до и после удаления поля.","priority_h5_target":"Доля отправленных заявок сохраняется или растёт.","priority_secondary_title":"Ещё две гипотезы из интервью","priority_dealer":"<strong>Выбор дилерского центра · средний приоритет.</strong> Клиенты хотели записываться в удобном салоне. Идея выделена в отдельную гипотезу. В рабочем приложении выбор дилера появился в форме.","priority_calculator":"<strong>Кредитный калькулятор · низкий приоритет.</strong> Участники видели пользу в расчёте кредита или рассрочки при выборе автомобиля. Расчёт внутри формы добавил бы ещё один шаг перед отправкой. Отдельный калькулятор оставлен как гипотеза для будущей проверки спроса.","priority_method_title":"Как определялась очерёдность","priority_moscow":"Оценены десять требований к оформлению заявки, работе менеджера и подготовке интерфейса. По <strong>MoSCoW</strong> в рабочей таблице выделены обязательные требования (Must) и важные требования, которые можно запланировать позже (Should).","priority_scales":"Затем каждое требование оценено по трём шкалам от 1 до 5. Чем больше число, тем сильнее ожидаемая польза для клиента, выше ценность для бизнеса или сложнее реализация.","priority_impact":"<strong>Impact</strong> Ожидаемое влияние на клиента. Например, насколько проще будет найти кнопку или выбрать время.","priority_effort":"<strong>Effort</strong> Время и сложность реализации. Например, выбор времени требует больше работы, чем изменение контраста кнопки.","priority_value":"<strong>Value</strong> Ожидаемая польза для бизнеса. Например, менеджер быстрее узнает о новой заявке и сможет связаться с клиентом.","priority_formula":"<strong>Итоговый балл = Impact + Value − Effort.</strong> У контрастных кнопок получилось 9 баллов (5 + 5 − 1). Это изменение получило высокие оценки пользы для клиента и бизнеса при минимальной сложности.","priority_table_title":"Рабочая таблица приоритизации","priority_table_hint":"На узком экране таблицу можно прокрутить вправо.","priority_roadmap_title":"Результат приоритизации","priority_roadmap_intro":"На этапе приоритизации задачи распределены по двум спринтам. План отражает требования к раннему варианту оформления и к работе с заявкой после отправки.","priority_sprint1":"Заметные кнопки, единое поле ФИО, выбор даты и времени и уведомление менеджера о новой заявке в системе работы с клиентами (CRM). Набор компонентов в Figma вошёл в первый спринт, потому что он нужен для сборки интерфейса.","priority_sprint2":"В плане были прогресс-бар для раннего пошагового прототипа, отказ от поля email, обработка сетевых ошибок и сохранение черновика. После проверки прототипа заполнение перенесено на один экран с прокруткой.","priority_backlog":"Аналитика помогает понять, сколько клиентов начинает и заканчивает оформление, но полноценный дашборд требовал больше ресурсов. В журнале решений он отложен.","priority_result":"В проверке раннего прототипа группа с индикатором заполняла форму в среднем за 47,4 с, группа без индикатора — за 52 с. Все десять участников завершили задачу. Долю незавершённых форм предстоит проверить на реальных заявках. <a href=\"#validation\">Посмотреть проверку прототипа</a>.","priority_conclusion":"<strong>Вывод.</strong> Первой версии нужен полный путь заявки: клиент может начать оформление, выбрать время, отправить данные и понять, что будет дальше, а менеджер получает обращение для работы. Именно поэтому выбор времени и передача заявки в CRM вошли в план раньше части более простых улучшений.","priority_goal":"<strong>Бизнес ориентируется на объём продаж, конверсию, средний чек дополнительных услуг и повторные обращения клиентов.</strong> Для сценария заявки выделены показатели, которые помогают понять, где теряются клиенты: время заполнения, доля отправленных заявок и доля обращений, которые доходят до визита.","priority_hypothesis_basis":"Гипотеза и основание","priority_hypotheses_hint":"Прокрутите таблицу вправо, чтобы увидеть способ проверки и критерий успеха.","validation_ab_title":"Что проверено на двух прототипах","validation_ab_intro":"В варианте A клиент переходил между экранами без индикатора. В варианте B на тех же экранах появились полоска прогресса и номер шага. Десять человек проходили сценарий, по пять на каждый вариант.","validation_intermediate_caption":"Промежуточный вариант B. Контактные данные и комментарий заполнялись на отдельных экранах, затем появлялось подтверждение.","validation_feedback_title":"Почему изменена структура формы","validation_feedback":"Во время проверки гипотезы респонденты предложили собрать заполнение на одном экране с прокруткой. В варианте B после контактов всё ещё нужно было нажать «Продолжить», чтобы добраться до комментария и отправки. В финальной форме клиент может пролистать поля, вернуться к любому из них и отправить заявку с того же экрана.","validation_final_title":"Покупка и тест-драйв. По одному экрану на заявку.","validation_final_intro":"Автомобиль, комплектация, город, дилер и контакты собраны на одном экране с прокруткой. Для тест-драйва на этом же экране можно выбрать дату и время визита.","validation_final_profile":"<strong>Контакты уже в форме.</strong> После входа ФИО и номер телефона подставляются из профиля. Их можно исправить прямо в заявке или указать данные другого человека. Например, муж может записать жену на тест-драйв со своего аккаунта и оставить её номер: ей не нужно устанавливать приложение и регистрироваться.","validation_purchase_caption":"Заявка на покупку","validation_drive_caption":"Запись на тест-драйв","validation_metrics_title":"Замеры прототипов и цели финальной формы","validation_metrics_intro":"Первые два столбца с результатами — замеры теста A/B. В последнем столбце — цели для следующей проверки финальной формы. Видео показывают, как она работает; для сравнения времени и ошибок нужно дать участникам сопоставимые задания.","validation_conclusion":"<strong>Вывод.</strong> Тест показал ценность понятной структуры, а обратная связь помогла убрать переход между экранами. В финальной форме эту структуру задают группы полей, данные из профиля сокращают повторный ввод, а экран подтверждения завершает сценарий.","reflection_sprint_note":"Эти показатели взяты из отчёта спринта, когда форма ещё была разбита на шаги. Замеры A/B и цели для финальной формы приведены в разделе пользовательской проверки.","validation_a_difference":"На экранах не указано, какой шаг сейчас открыт.","validation_b_difference":"Рамками отмечены полоска прогресса и номер шага: 1/3, 2/3 и 3/3.","validation_goal_label":"Цель следующей проверки","validation_goal_time":"≤ 40 с","decisions_intro":"По результатам исследования выявлены три требования к заявке: начать с карточки выбранного автомобиля, легко проверить и исправить данные, а после отправки понять, что заявка получена и кто свяжется дальше. На примере тест-драйва сравнены три способа заполнения.","decisions_tradeoff":"Компромисс","decisions_option_1":"Форма поверх карточки","decisions_option_1_body":"По кнопке записи снизу открывается панель (bottom sheet). Клиент видит выбранную модель, пока выбирает время и вводит контакты в панели.","decisions_option_1_tradeoff":"Если форма длинная, в компактной панели сложнее одновременно видеть календарь, поля и кнопку отправки. Для показа свободных слотов нужны актуальные данные дилера.","decisions_option_2":"Чат-помощник","decisions_option_2_body":"Бот или менеджер по очереди спрашивает про время и контакты. В диалоге удобно уточнить детали. Например, можно спросить про комплектацию перед записью.","decisions_option_2_tradeoff":"Каждый ответ добавляет шаг. Чтобы исправить прежний выбор, нужно вернуться к нему в диалоге. Для работы чата требуется бот или оператор.","decisions_option_3":"Форма с закреплённой кнопкой","decisions_option_3_body":"Календарь, контакты и необязательный комментарий собраны в одной форме. Кнопка отправки остаётся видимой при прокрутке.","decisions_option_3_tradeoff":"На телефоне длинная форма может выглядеть перегруженной, а закреплённая кнопка занимает место рядом с клавиатурой. Помогают чёткий порядок и группировка полей.","decisions_selected_title":"Что взято из этих подходов","decisions_selected":"Из нижней панели позаимствовано открытие заявки прямо из карточки автомобиля, из формы с закреплённой кнопкой — идея собрать параметры в одном месте. Вопросы менеджеру полезны, когда клиент ещё выбирает, а для самой заявки лучше подходят поля, которые можно просмотреть и исправить в любом порядке.","decisions_wireframes_intro":"На вайрфреймах связаны каталог, карточку модели и комплектации. Это помогло определить, откуда человек начинает оформление и какие параметры уже выбраны к этому моменту.","decisions_evolution":"От пошагового прототипа к финальной форме","decisions_test_title":"Что показал тест","decisions_test":"На двух версиях пошагового прототипа проверено, помогает ли индикатор понять, сколько осталось. С ним участники дошли до подтверждения в среднем за <strong>47,4 с</strong>, без него — за <strong>52 с</strong>. Респонденты предложили убрать переход по кнопке «Продолжить» и собрать заполнение на одном экране.","decisions_final_title":"Что изменено в приложении","decisions_final":"В финале обе заявки заполняются на одном экране с прокруткой. Нумерация групп показывает структуру, а к любому полю можно вернуться прокруткой. ФИО и телефон подставляются из профиля, их можно изменить, в том числе при оформлении за другого человека.","decisions_purchase_title":"Покупка","decisions_purchase":"Модель, комплектация, город, дилер и контакты.","decisions_drive_title":"Тест-драйв","decisions_drive":"Те же данные, плюс дата и время визита.","decisions_outcome":"<strong>Вывод.</strong> Индикатор помогал ориентироваться, пока форма была разбита на экраны. В финальной версии эту задачу выполняют группы полей, а отдельный экран после отправки показывает выбранный автомобиль и его комплектацию, анимацией подтверждает успешную отправку и объясняет, что дальше свяжется менеджер.","decisions_test_link":"Сравнить прототипы и результаты","decisions_final_link":"Посмотреть оба сценария в приложении","mood_title":"Автомобиль, материалы и детали.","mood_kicker":"Визуальное направление","mood_prev":"Предыдущее фото","mood_next":"Следующее фото","mood_select":"Выбрать модель","mood_photo_0":"ELANTRA · вид спереди","mood_photo_1":"ELANTRA · салон","mood_photo_2":"ELANTRA · детали","mood_photo_3":"SONATA · вид спереди","mood_photo_4":"SONATA · салон","mood_photo_5":"SONATA · детали","mood_photo_6":"TUCSON · вид спереди","mood_photo_7":"TUCSON · салон","mood_photo_8":"TUCSON · детали","mood_photo_9":"SANTA FE · вид спереди","mood_photo_10":"SANTA FE · салон","mood_photo_11":"SANTA FE · детали","role_heading":"Моя роль","project_role_1":"<strong>Исследование.</strong> Интервью с респондентами, анализ барьеров и контекстов использования, две персоны и CJM.","project_role_2":"<strong>Продуктовая проработка.</strong> Формулировка гипотез и критериев успеха, приоритизация требований, проектирование сценариев покупки, тест-драйва и обработки заявки в CRM.","project_role_3":"<strong>UX/UI и проверка.</strong> Информационная архитектура, вайрфреймы, прототипы, дизайн-система, дизайн-ревью, A/B-тест и проверка текстов интерфейса.","project_role_4":"<strong>Реализация.</strong> Пользовательские истории, нетипичные сценарии и критерии приёмки, разработка iOS-приложения на Swift и интерактивной веб-версии для портфолио.","cjm_stage":"Этап пути","cjm_action":"Действие","cjm_barrier":"Барьер","cjm_response":"Ответ интерфейса","cjm_1_0":"Знакомство","cjm_1_1":"Определить интересующую модель.","cjm_1_2":"—","cjm_1_3":"Фотографии и преимущества автомобилей в каталоге.","cjm_2_0":"Выбор автомобиля","cjm_2_1":"Сравнить модели, цены и комплектации.","cjm_2_2":"Сложно быстро найти различия.","cjm_2_3":"Каталог и таблица сравнения комплектаций.","cjm_3_0":"Переход к записи","cjm_3_1":"Открыть заявку, выбрать город и дилера.","cjm_3_2":"Кнопку записи трудно найти на карточке автомобиля.","cjm_3_3":"Заметная кнопка «Записаться на тест-драйв». Город и дилер выбираются в форме.","cjm_4_0":"Выбор времени","cjm_4_1":"Указать удобные дату и время визита.","cjm_4_2":"Приходится уточнять время отдельно.","cjm_4_3":"Дата и время выбираются в той же форме, менеджер подтверждает визит.","cjm_5_0":"Контактные данные","cjm_5_1":"Проверить ФИО и номер телефона, при необходимости изменить их.","cjm_5_2":"Лишние поля и повторный ввод увеличивают нагрузку.","cjm_5_3":"ФИО и номер телефона подставляются из профиля в два поля. Оба поля можно отредактировать на том же экране.","cjm_6_0":"Отправка заявки","cjm_6_1":"Проверить данные и отправить заявку.","cjm_6_2":"Без обратной связи непонятно, принята ли заявка.","cjm_6_3":"Отдельный экран подтверждает отправку анимацией, показывает автомобиль и комплектацию и сообщает о звонке менеджера.","cjm_7_0":"Подтверждение визита","cjm_7_1":"Получить ответ менеджера и приехать в салон.","cjm_7_2":"Неясно, кто обрабатывает заявку и куда ехать.","cjm_7_3":"Статус и адрес дилера доступны в разделе заявок. Из карточки можно построить маршрут.","cjm_table_hint":"На узком экране таблицу можно прокрутить вправо.","priority_sprint1_title":"Спринт 1 · основа заявки.","priority_sprint2_title":"Спринт 2 · заполнение и сбои.","priority_backlog_title":"Позже · дашборд заявок.","mood_photo_12":"PALISADE · вид спереди","mood_photo_13":"PALISADE · салон","mood_photo_14":"PALISADE · детали","mood_photo_15":"STARIA · вид спереди","mood_photo_16":"STARIA · салон","mood_photo_17":"STARIA · детали","validation_final_kicker":"Финальная версия","validation_purchase_detail":"Выбор комплектации и дилера с контактами из профиля.","validation_drive_detail":"Выбор дилера, даты и времени визита в той же форме."},"en":{"hero_eyebrow":"01 / Featured case study · 2026","hero_title":"Drive&amp;Deal <span style=\"color:var(--accent)\">Showroom.</span>","hero_lead":"From choosing a car to submitting and managing a request — an iPhone app.","hero_note":"Research, UX/UI and a working iOS prototype. The app was designed and implemented independently with Codex.","hero_tag_0":"UX research","hero_tag_1":"Product design","hero_tag_2":"iOS","hero_tag_3":"CRM","hero_cta":"Explore the case <span class=\"dd-cta-arrow\" aria-hidden=\"true\">↘</span>","eyebrow_1":"02 / Context and challenge","s02_00":"Drive&amp;Deal. A car showroom designed from scratch for iPhone.","s02_01":"Drive&amp;Deal began as a self-directed product initiative. There was no brief or predefined flow. The project goal was defined from scratch: help people choose a car, book a test drive or submit a purchase request, and give the dealership a way to follow up through the visit.","s02_02":"Customers explore models, compare trims and submit a request from one scrollable screen. The app confirms submission, shows its status and explains what happens next. The manager receives the request in the CRM, contacts the customer, clarifies the details, agrees on a visit and updates the status. Before the visit, they prepare the chosen car or information about trims and purchase terms. At the showroom, they meet the customer and lead the test drive or discuss the purchase, depending on the request.","s02_03":"The entire project was completed independently, from defining the problem and conducting research to building a working iPhone app.","s02_04":"<strong>Platform:</strong> iPhone.","s02_05":"<strong>Tools:</strong> Figma, Swift, Xcode, Codex.","s02_06":"<strong>MVP focus:</strong> the catalog, car details, trims, request submission and request management.","s02_07":"Three needs that shaped the interface","s02_08":"<li><strong>Compare before deciding.</strong> Photos, prices and trim specifications should help people choose a car.</li><li><strong>Make requests easier to fill out.</strong> Required fields, screen transitions and button visibility shape how customers fill out requests.</li><li><strong>Understand the request status.</strong> After submission, people need confirmation, a status and a clear way to continue the conversation with the dealer.</li>","eyebrow_2":"03 / Research","s03_00":"Where people lose confidence.","s03_01":"The research included three in-depth interviews with 15 questions across seven topics. It covered how customers choose a car, fill out a request and expect to hear from a manager.<br>The interviews informed two personas and a seven-stage customer journey map (CJM).","s03_02":"Key findings from the research","s03_03":"<strong>Primary actions need to be easier to find.</strong> Participants expected a visible way to request a purchase or test drive. The car details screen gives these actions a clearer visual hierarchy.","s03_04":"<strong>Three input fields felt like extra work.</strong> First name, last name and patronymic were combined into one field. The final form uses a phone number for follow-up, which can be checked and edited before submission.","s03_05":"<strong>A progress bar helped show how much was left.</strong> The early prototype added a progress bar so users could tell which step they were on and how many were left. In the final form, numbered field groups provide that structure on a single scrollable screen.","s03_06":"<strong>The form fits on one scrollable screen.</strong> During testing, participants suggested bringing the request fields and the separate comment screen together. In the final version, customers can return to any field and submit the request from the same screen.","s03_07":"<strong>Choosing a time matters before a manager calls.</strong> Date and time are selected directly in the test-drive form.","s03_08":"<strong>Confirmation should explain what happens next.</strong> Customers need to see their chosen car, the request status, a clear indication that it was submitted successfully and what to expect next.","s03_09":"CJM: from interest to confirmation","s03_11":"When reviewing contact details, customers need to see what came from their profile and be able to edit it. After submission, they need confirmation that the request was received and clarity on what happens next. The manager sees the new request in the CRM and contacts the customer to confirm the visit.","s03_12":"Three situations were considered for submitting a purchase or test-drive request: in a quiet setting, outdoors, and in a hurry with a weak connection. Both flows require choosing a car and dealer, reviewing contact details and getting confirmation. Test drives also require a date and time.","cjm_alt":"Customer journey map with tasks, friction points and opportunities to improve request submission.","cjm":"Original customer journey map from the research. It captures early hypotheses, including a progress bar for the step-by-step prototype.","eyebrow_3":"04 / Hypotheses and priorities","s04_00":"Prioritise changes along the core request journey.","s04_01":"The interviews and journey map revealed three obstacles: the right action was hard to find, the form asked for unnecessary information, and customers were unsure whether their request went through. The goal for the first working version (MVP) was to cover the full journey from choosing a car to getting a request into a manager’s hands.","s04_02":"<thead><tr><th scope=\"col\">Requirement</th><th scope=\"col\">MoSCoW</th><th scope=\"col\">Impact</th><th scope=\"col\">Effort</th><th scope=\"col\">Value</th><th scope=\"col\">Score</th></tr></thead><tbody><tr><th scope=\"row\">High-contrast purchase and booking buttons</th><td>Must</td><td>5</td><td>1</td><td>5</td><td>9</td></tr><tr><th scope=\"row\">One full-name field</th><td>Must</td><td>4</td><td>1</td><td>4</td><td>7</td></tr><tr><th scope=\"row\">Progress bar in the early prototype</th><td>Must</td><td>4</td><td>2</td><td>4</td><td>6</td></tr><tr><th scope=\"row\">Choose a date and time without calling</th><td>Must</td><td>5</td><td>3</td><td>5</td><td>7</td></tr><tr><th scope=\"row\">Form without an email field</th><td>Should</td><td>3</td><td>1</td><td>3</td><td>5</td></tr><tr><th scope=\"row\">Notify the manager in CRM</th><td>Must</td><td>4</td><td>3</td><td>5</td><td>6</td></tr><tr><th scope=\"row\">Request analytics dashboard</th><td>Should</td><td>3</td><td>4</td><td>4</td><td>3</td></tr><tr><th scope=\"row\">Figma UI kit</th><td>Must</td><td>4</td><td>2</td><td>3</td><td>5</td></tr><tr><th scope=\"row\">Handling network errors</th><td>Should</td><td>4</td><td>3</td><td>4</td><td>5</td></tr><tr><th scope=\"row\">Save a request draft</th><td>Should</td><td>3</td><td>3</td><td>3</td><td>3</td></tr></tbody>","eyebrow_4":"05 / Interaction design","s05_00":"Three approaches to booking.","wireframes_alt":"Early wireframes of the home screen, catalog views, car details and trims.","wireframes":"Wireframes are simplified layouts of the future app interface, showing the catalog structure and the car-selection journey.","eyebrow_5":"06 / App interface","s06_00":"From the catalog to a specific car.","app_0_alt":"Drive&Deal home screen with search and popular models.","app_0":"01 — Home and popular models.","s06_01":"<strong>Catalog and search.</strong> Popular models on the home screen and a dedicated model list provide routes to a car and help people find the model they want.","app_1_alt":"Hyundai ELANTRA details with photos, benefits, and purchase and test-drive actions.","app_1":"02 — Car details and actions.","s06_02":"<strong>Car details.</strong> Photos, benefits, trims and actions are organised around the selected model. Purchase and test-drive actions use distinct labels and styling.","app_2_alt":"Hyundai ELANTRA trims compared by price, specifications and equipment.","app_2":"03 — Trim comparison.","s06_03":"<strong>Trim comparison.</strong> A single table brings together price, engine, transmission and equipment. People can assess the differences before contacting the dealer.","app_3_alt":"Test-drive form with the car, trim, dealer, date, time and contact details.","app_3":"04 — Final test-drive request form.","s06_04":"<strong>Submitting a request.</strong> The final form puts the car, trim, city, dealer and contact details on one scrollable screen. A test-drive request also includes a date and time. The name and phone number come from the profile and can be changed before submission.","s06_07":"Watch the customer journey ↗","eyebrow_6":"07 / Request management","s07_00":"Two sides of the same request.","s07_01":"The customer chooses a car, submits a request and follows its status. The manager receives the details in the CRM and helps turn the request into a showroom visit.","s07_02":"<li><span class=\"dd-flow-index\">01</span><span>Choose a car</span></li><li><span class=\"dd-flow-index\">02</span><span>Submit a request</span></li><li><span class=\"dd-flow-index\">03</span><span>Manager review</span></li><li><span class=\"dd-flow-index\">04</span><span>Customer checks the status</span></li>","s07_03":"For customers: requests and statuses","s07_04":"Purchase and test-drive requests are accessible through the profile and requests section. The details include the car, trim, dealer, contact information and current status. A customer can cancel a request.","role_0_alt":"Customer test-drive and purchase requests with statuses in dark appearance.","role_0":"Customer — request list.","s07_05":"Watch the customer journey ↗","s07_06":"For managers: request management","s07_07":"The CRM panel separates purchase and test-drive enquiries. Each card contains customer and car information, a status, and actions for calling, WhatsApp and Telegram.","role_1_alt":"CRM panel with customer and car details, statuses and contact actions.","role_1":"Manager — CRM panel.","s07_08":"Watch the CRM workflow ↗","maps_alt":"Purchase request details with the dealer address, contact information and cancellation.","maps":"Request details and dealer address.","s07_09":"Next action: directions to the dealer","s07_10":"The dealer&#x27;s address is available in the request details. Map links let people get directions without copying the address, with a choice of Apple Maps, Yandex Maps or 2GIS.","s07_11":"Watch map navigation ↗","eyebrow_7":"08 / Design system","s08_00":"Components, states and two appearances.","s08_01":"The design system documents typography, layout, colours and components for light and dark appearances. It also specifies element behaviour and screen transitions.","s08_02":"<strong>Typography.</strong> SF Pro Display and SF Pro Text, with a hierarchy spanning model names and prices, specifications and supporting labels.","s08_03":"<strong>Components.</strong> Car and trim cards, action buttons, form fields, navigation, statuses and confirmations.","s08_04":"<strong>States.</strong> Default, pressed, disabled, error and success. Colour and text communicate the state of an element or request.","s08_05":"<strong>Two appearances.</strong> Light and dark palettes with a consistent hierarchy of text, surfaces and accents.","s08_06":"The documentation sets out acceptance criteria for navigation from car details, trim displays, scrolling, narrow-screen behaviour and contrast.","system_alt":"Drive&Deal design system with typography, palettes, layout and component states.","system":"Light and dark appearances, components and states.","eyebrow_8":"09 / User validation","s09_00":"From three screens to one form.","s09_01":"The first design question was whether a progress indicator would make it clear how much was left before submission. Comparing two prototypes answered that question and pointed to a shorter path to submission.","test_0_alt":"Variant A: contact details, comment and confirmation without a progress indicator.","test_0":"Variant A · prototype without an indicator.","test_1_alt":"Variant B: the same three screens with 1/3, 2/3 and 3/3 progress indicators in the upper-right corner.","test_1":"Variant B · intermediate prototype with a progress indicator.","s09_02":"<thead><tr><th scope=\"col\">Measure</th><th scope=\"col\">Without an indicator</th><th scope=\"col\">With an indicator</th><th scope=\"col\">Final form · target</th></tr></thead><tbody><tr><th scope=\"row\">Mean completion time</th><td>52 s</td><td>47.4 s</td><td>≤ 40 s</td></tr><tr><th scope=\"row\">Mean errors per participant</th><td>0.4</td><td>0</td><td>0</td></tr><tr><th scope=\"row\">Mean repeated actions per participant</th><td>0.6</td><td>0</td><td>0</td></tr><tr><th scope=\"row\">Process clarity</th><td>3.8 / 5</td><td>5 / 5</td><td>5 / 5</td></tr><tr><th scope=\"row\">Confidence in completion</th><td>3.4 / 5</td><td>5 / 5</td><td>5 / 5</td></tr></tbody>","s09_03":"Both groups reached confirmation. Participants with the indicator finished an average of 4.6 seconds faster, and this group recorded no errors or repeated actions. The test highlighted the importance of making the form’s structure visible.","s09_04":"On average for a customer with a completed profile. This is about <strong>16% below</strong> the measured time for variant B. The aim is to match variant B on errors, repeated actions, clarity and confidence.","s09_05":"Labels: explain the action before the tap","s09_06":"The wording was also tested with four participants. In the multi-step prototype, Continue meant moving to the next screen. In the final form, the primary button names the action it performs: submitting a purchase request or requesting a test drive.","s09_07":"After submission, an animation confirms success. The screen shows the car and trim in the request. For a test drive, the manager then calls to confirm the visit.","eyebrow_9":"10 / Outcomes and reflection","s10_00":"From research to a working app.","s10_01":"The project went from interviews, journey mapping and wireframes to a working iPhone app. Codex was used to implement the catalog, car details, trim comparison, purchase and test-drive forms, request history, the CRM panel and map navigation.","s10_02":"Metrics from the intermediate sprint","result_0":"45 → 20 s","result_detail_0":"approximately 55% shorter","result_label_0":"Form completion time","result_1":"40% → 18%","result_detail_1":"down 22 percentage points","result_label_1":"Drop-off at step three","result_2":"+28%","result_detail_2":"relative to baseline","result_label_2":"Request conversion","result_3":"+45%","result_detail_3":"relative to baseline","result_label_3":"Clicks on “Buy”","s10_04":"What changed in the product","s10_05":"The final form collects the request on one scrollable screen. Customers choose the city and dealer, then review and edit their prefilled name and phone if needed. Test-drive customers can also choose a date and time on the same screen.","s10_06":"Implementation made it possible to examine these decisions as a connected sequence: choose a car, submit a request, review it as a customer and move to the CRM panel for processing.","s10_07":"Next iteration","s10_08":"The next test will compare completion time, errors and repeated actions on equivalent tasks in the final form. It will also cover booking on someone else’s behalf and what happens to entered data on a weak connection.","system_board":"<div class=\"dd-system-top\"><div><span class=\"dd-system-kicker\">Interface foundations</span><h3>One system. Two appearances.</h3></div><div class=\"dd-theme-switch\" role=\"group\" aria-label=\"Sample appearance\"><button type=\"button\" data-dd-theme=\"light\" aria-pressed=\"true\">Light</button><button type=\"button\" data-dd-theme=\"dark\" aria-pressed=\"false\">Dark</button></div></div>\n <h4>Colour palette</h4><ul class=\"dd-palette\"><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-primary)\"></span><strong>Primary</strong><code><span class=\"dd-token-light\">#002C5F</span><span class=\"dd-token-dark\">#263F72</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-secondary)\"></span><strong>Secondary</strong><code><span class=\"dd-token-light\">#007FA8</span><span class=\"dd-token-dark\">#4DD9FF</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-text)\"></span><strong>Text</strong><code><span class=\"dd-token-light\">#1A1A1A</span><span class=\"dd-token-dark\">#FFFFFF</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-muted)\"></span><strong>Secondary text</strong><code><span class=\"dd-token-light\">#666666</span><span class=\"dd-token-dark\">#8E8E93</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-background)\"></span><strong>Background</strong><code><span class=\"dd-token-light\">#F5F6F8</span><span class=\"dd-token-dark\">#000000</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-border)\"></span><strong>Border</strong><code><span class=\"dd-token-light\">#E0E0E0</span><span class=\"dd-token-dark\">#404047</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-success)\"></span><strong>Success</strong><code><span class=\"dd-token-light\">#4CAF50</span><span class=\"dd-token-dark\">#4CAF50</span></code></li><li><span class=\"dd-token-swatch\" style=\"background:var(--ds-error)\"></span><strong>Error</strong><code><span class=\"dd-token-light\">#F44336</span><span class=\"dd-token-dark\">#F44336</span></code></li></ul>\n <div class=\"dd-system-details\"><section class=\"dd-type-section\"><h4>Typography</h4><p>SF Pro Display · SF Pro Text</p><ul class=\"dd-type-list\"><li><span class=\"dd-type-meta\">28 · 700</span><span style=\"font-size:28px;font-weight:700\">Hyundai ELANTRA</span><small>Model name</small></li><li><span class=\"dd-type-meta\">22 · 700</span><span style=\"font-size:22px;font-weight:700\">Car price</span><small>Price</small></li><li><span class=\"dd-type-meta\">18 · 600</span><span style=\"font-size:18px;font-weight:600\">Trims and prices</span><small>Section heading</small></li><li><span class=\"dd-type-meta\">15 · 400</span><span style=\"font-size:15px;font-weight:400\">Choose a suitable date and time.</span><small>Body text</small></li><li><span class=\"dd-type-meta\">13 · 400</span><span style=\"font-size:13px;font-weight:400\">Additional information</span><small>Caption</small></li></ul></section><section><h4>Spacing and rhythm</h4><p>Base spacing scale</p><ul class=\"dd-spacing\"><li><span style=\"width:12px\"></span><code>4</code></li><li><span style=\"width:24px\"></span><code>8</code></li><li><span style=\"width:48px\"></span><code>16</code></li><li><span style=\"width:72px\"></span><code>24</code></li><li><span style=\"width:96px\"></span><code>32</code></li></ul><div class=\"dd-spacing-notes\"><span>16 px — screen margins</span><span>24 px — between sections</span></div><h4>Transitions</h4><dl class=\"dd-motion-list\"><div><dt>New screen</dt><dd>300 ms</dd></div><div><dt>Gallery</dt><dd>800 ms</dd></div><div><dt>Progress bar · early prototype</dt><dd>400 ms</dd></div></dl></section></div>\n <section class=\"dd-component-section\"><h4>Components and states</h4><div class=\"dd-component-grid\"><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Primary action</span><button type=\"button\" class=\"dd-sample-button\" data-dd-sample>Buy</button><small>Hover and press</small></div><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Disabled action</span><button type=\"button\" class=\"dd-sample-button\" disabled>Continue</button><small>Disabled state</small></div><div class=\"dd-component-sample\"><span class=\"dd-sample-label\">Feedback</span><span class=\"dd-sample-feedback\">✓ Request submitted</span><span class=\"dd-sample-error\">Check the phone number</span></div></div></section>","customer_kicker":"Customer experience","customer_title":"The customer journey: from discovery to a dealer visit.","customer_intro":"The catalog, comparison, purchase and test-drive flows form a connected journey. After submitting a request, customers can follow its status and get directions to the dealer.","full_title":"The complete app: the full customer journey","full_description":"A complete walkthrough of the app, from exploring models and comparing trims to submitting and managing requests. This recording shows the product’s functionality and how its sections connect.","full_meta":"Complete app walkthrough","purchase_title":"Purchase: from selection to submission","purchase_description":"In the final form, the customer chooses the car, trim, city and dealer, reviews the profile contact details, and submits from the same screen. The confirmation shows the selected car and trim.","test_drive_title":"Test drive: from interest to booking","test_drive_description":"Booking uses the same form with a date and time for the visit. Customers can edit their name and phone before submitting. The app then explains that a manager will get in touch to confirm the test drive.","status_title":"Requests and statuses: what happens after submission","status_description":"The request list keeps customers in control after submission. Purchase and test-drive requests are collected here, with the car, trim, dealer, contact details and current status available in each record. A request can be cancelled if plans change.","route_title":"Directions to the dealer: the next step towards a visit","route_description":"The dealer’s address is available in the request. Customers can open it in Apple Maps, Yandex Maps or 2GIS and get directions without copying the address.","employee_kicker":"Employee workflow","employee_title":"The manager’s workspace. From request to visit.","employee_intro":"The CRM shows who submitted the request, which car they chose and why they plan to visit. The manager contacts the customer, agrees on a visit and updates the status. They then prepare the car for a test drive or a purchase proposal.","manager_title":"Managing requests in CRM","manager_description":"Purchase and test-drive requests are separated by request type. Each card shows the customer, car, trim and status, with actions to call or open WhatsApp and Telegram. Context and the next action sit together.","cjm_conclusion":"<strong>Takeaway.</strong> Dealer and time selection, contact details and the comment are grouped on one scrollable screen. Confirmation closes the form, and the status in My Requests shows what happens next.","context_title":"Context of use","context_conditions":"Conditions","context_risk":"Possible errors and failures","context_response":"Design requirements","context_quiet_title":"Quiet setting","context_quiet_level":"Low cognitive load","context_quiet_conditions":"A quiet office, stable Wi-Fi and both hands free.","context_quiet_risk":"Even without time pressure, a customer can mistype a number or choose the wrong date. A quiet setting makes it easier to spot and correct the error before submitting.","context_quiet_response":"A clear field order, easy-to-find consent terms and a chance to review details before submitting.","context_street_title":"Outdoors","context_street_level":"Moderate cognitive load","context_street_conditions":"Noise, glare and distractions. One hand is occupied.","context_street_risk":"Glare and distractions make it easy to mistype a number, miss the consent checkbox or lose track of a section while scrolling.","context_street_response":"Use large, high-contrast buttons and a visible checkbox. Group related fields and show the phone format and errors close to the relevant input.","context_rush_title":"Rushed, with a weak connection","context_rush_level":"High cognitive load","context_rush_conditions":"Limited time, poor visibility and an unstable 2G/3G connection.","context_rush_risk":"The form may fail to load, or submission may be interrupted. If the result is unclear, the customer may tap Send again and create a duplicate request.","context_rush_response":"Keep required fields to a minimum. Show loading, preserve entered details after an error and allow a retry without duplicate requests. Confirm when the request is received.","cjm_intro":"The customer journey map (CJM) follows a test-drive request from choosing a model to the visit.<br>The Interface response column describes the final design. Two stages are highlighted<br>where customers especially need clarity: reviewing contacts and submitting the request.","context_comparison":"<strong>What the comparison showed.</strong> In a quiet setting, it is easier to review details before submitting. Outdoors, it is harder to see a field or hint. With a weak connection, even a correctly filled request may not reach the dealer. The form needs to support customers both as they enter their details and after they tap Send.","context_conclusion":"<strong>Takeaway.</strong> Keep only the necessary fields, show errors next to them, and tell customers when their request is being sent and when the dealer has received it. If the connection drops, customers should be able to retry with the same details without creating a second request.","priority_hypotheses_title":"What was worth testing","priority_hypotheses_intro":"The interviews informed five core hypotheses. Each one identifies a change, how to compare the alternatives and how to assess the outcome.","priority_check":"Planned test","priority_target":"Success criterion","priority_h1_title":"Visible purchase and test-drive buttons","priority_h1_reason":"Customers wanted to find the right action faster on the car page.","priority_h1_check":"Compare the original car page with a version that makes the two actions easier to distinguish.","priority_h1_target":"At least 15% more clicks on Buy.","priority_h2_title":"One full-name field","priority_h2_reason":"Entering a name in three fields took more time.","priority_h2_check":"Compare completion time for forms with three fields and one field.","priority_h2_target":"At least 30% less time to fill in the form.","priority_h3_title":"Choose a test-drive date and time","priority_h3_reason":"Customers wanted to see available times and book without a separate call.","priority_h3_check":"Compare the form with available time slots against the original.","priority_h3_target":"At least 20% more completed requests.","priority_h4_title":"Progress bar in the early prototype","priority_h4_reason":"Customers were unsure how much of the form was left.","priority_h4_check":"Compare two versions of the same prototype flow, with and without the indicator.","priority_h4_target":"At least 20% fewer abandoned forms.","priority_h5_title":"Phone contact without an email field","priority_h5_reason":"Interview participants described phone calls as their main way of contacting the dealer.","priority_h5_check":"Compare the share of people who submit after starting the form, before and after removing the field.","priority_h5_target":"The submission rate stays the same or increases.","priority_secondary_title":"Two further ideas from the interviews","priority_dealer":"<strong>Choice of dealer · medium priority.</strong> Customers wanted to book at a convenient showroom. This became a separate hypothesis. The working app includes dealer selection in the form.","priority_calculator":"<strong>Finance calculator · low priority.</strong> Participants saw value in estimating loan or instalment costs while choosing a car. Putting the estimate before submission would add another decision to the booking flow. A standalone calculator was kept as a hypothesis for testing future demand.","priority_method_title":"How priorities were set","priority_moscow":"Ten requirements were evaluated across the request flow, manager workflow and design preparation. The working table uses <strong>MoSCoW</strong> to distinguish essential requirements (Must) from important requirements that can be scheduled later (Should).","priority_scales":"Each requirement was then scored on three scales from 1 to 5. A higher number means greater expected benefit for the customer, more business value or more effort to implement.","priority_impact":"<strong>Impact</strong> Expected benefit to the customer, such as how much easier it would be to find a button or choose a time.","priority_effort":"<strong>Effort</strong> Time and implementation complexity. For example, offering time slots takes more work than changing a button’s contrast.","priority_value":"<strong>Value</strong> Expected business benefit. For example, a manager can learn about a new request sooner and follow up.","priority_formula":"<strong>Priority score = Impact + Value − Effort.</strong> More visible buttons scored 9 (5 + 5 − 1). The change was rated highly for customer and business benefit with minimal implementation effort.","priority_table_title":"Workshop prioritisation table","priority_table_hint":"On narrow screens, scroll the table to see all columns.","priority_roadmap_title":"How the priorities shaped the plan","priority_roadmap_intro":"At the prioritisation stage, the work was split across two sprints. This plan reflects the early request design and the work that follows submission.","priority_sprint1":"Visible buttons, one full-name field, date and time selection, and a notification in the customer relationship management system (CRM). The Figma UI kit was included because the interface depended on it.","priority_sprint2":"The plan included a progress bar for the early step-by-step prototype, removing the email field, handling network errors and saving drafts. After prototype testing, the fields were moved onto one scrollable screen.","priority_backlog":"Analytics helps track how many customers start and complete the form, but a full dashboard required more resources. The decision log deferred it.","priority_result":"In the early prototype test, the group with the indicator completed the form in 47.4 seconds on average, compared with 52 seconds without it. All ten participants completed the task. Abandonment still needs to be measured on real requests. <a href=\"#validation\">See the prototype test</a>.","priority_conclusion":"<strong>Takeaway.</strong> The first version needed a complete request journey: customers can start the form, choose a time, submit their details and know what happens next, while managers get a request they can act on. That is why time selection and CRM handoff were planned ahead of some simpler improvements.","priority_goal":"<strong>The business tracks sales volume, conversion, average spend on add-on services and repeat customer inquiries.</strong> The request flow has its own diagnostic metrics: completion time, submission rate and the share of requests that lead to a visit.","priority_hypothesis_basis":"Hypothesis and rationale","priority_hypotheses_hint":"Scroll the table right to see the planned test and the success criterion.","validation_ab_title":"What the two prototypes tested","validation_ab_intro":"In variant A, customers moved between screens without a progress indicator. Variant B added a progress bar and step number to the same screens. Ten people completed the flow, five in each group.","validation_intermediate_caption":"Intermediate variant B. Contact details and the comment were entered on separate screens before confirmation.","validation_feedback_title":"Why the form structure changed","validation_feedback":"While testing the hypothesis, participants suggested putting the fields on one scrollable screen. Variant B still required tapping Continue after entering contact details to reach the comment and submit the request. In the final form, customers can scroll through the fields, return to any of them and submit from the same screen.","validation_final_title":"Purchase or test drive. One screen per request.","validation_final_intro":"Car, trim, city, dealer and contact details are on one scrollable screen. For test drives, customers can also select the date and time of the visit.","validation_final_profile":"<strong>Contact details are ready to review.</strong> After signing in, the form fills in the customer’s full name and phone number from their profile. They can edit both fields in the request or enter someone else’s details. For example, a husband can book a test drive for his wife from his own account and enter her number, so she does not need to install the app or register.","validation_purchase_caption":"Purchase request","validation_drive_caption":"Test-drive booking","validation_metrics_title":"Prototype measurements and goals for the final form","validation_metrics_intro":"The first two result columns contain the A/B test measurements. The last column sets goals for the next test of the final form. The videos demonstrate the flow; comparing time and errors requires comparable tasks for participants.","validation_conclusion":"<strong>Takeaway.</strong> The test showed the value of a clear structure, and participant feedback helped remove a screen transition. In the final form, sections provide that structure, profile details reduce retyping, and confirmation closes the flow.","reflection_sprint_note":"These figures come from the sprint report, when the form still had multiple steps. The user-testing section shows the A/B measurements and the goals for the final form.","validation_a_difference":"The screens do not show which step is open.","validation_b_difference":"The outlines mark the progress bar and step number: 1/3, 2/3 and 3/3.","validation_goal_label":"Goal for the next test","validation_goal_time":"≤ 40 s","decisions_intro":"The research identified three requirements: start from the selected car’s details, make information easy to review and edit, and confirm that the request was received and who will follow up. Three ways to fill out the test-drive form were compared.","decisions_tradeoff":"Trade-off","decisions_option_1":"Form over the car details","decisions_option_1_body":"Tapping the booking button opens a bottom sheet over the car details. Customers stay in context while choosing a time and entering their contact details.","decisions_option_1_tradeoff":"A compact sheet makes it harder to see the calendar, fields and submit button together in a longer form. Showing available slots requires up-to-date dealer availability.","decisions_option_2":"Chat assistant","decisions_option_2_body":"A bot or manager asks for the time and contact details in sequence. Customers can ask a question about a trim before booking.","decisions_option_2_tradeoff":"Each answer adds a step. Editing an earlier choice means returning to it in the conversation. The chat needs a bot or an operator.","decisions_option_3":"Form with a fixed submit button","decisions_option_3_body":"The calendar, contact details and optional comment are grouped in one form. The submit button stays visible while scrolling.","decisions_option_3_tradeoff":"A long form can feel crowded on a phone, and the fixed button takes up space next to the keyboard. A clear order and grouping make fields easier to scan.","decisions_selected_title":"What carried over from the three approaches","decisions_selected":"The bottom sheet made it possible to open the request from the car details screen. The form with a fixed button brought all request details together. A conversation with a manager helps customers who are still deciding. For submitting a request, fields that can be reviewed and edited in any order are a better fit.","decisions_wireframes_intro":"The wireframes connect the catalog, car details and trims. They show where customers start a request and which details are already selected at that point.","decisions_evolution":"From the step-by-step prototype to the final form","decisions_test_title":"What the test showed","decisions_test":"Two versions of the same prototype were used to test whether a progress indicator made the remaining steps clearer. Participants reached confirmation in <strong>47.4 s</strong> on average with the indicator and <strong>52 s</strong> without it. Participants suggested removing the Continue step and putting the fields on one screen.","decisions_final_title":"What changed in the app","decisions_final":"In the final app, both requests use one scrollable form. Numbered sections show how it is organised, and customers can scroll back to any field. Full name and phone number come from the profile and can be edited, including when booking for someone else.","decisions_purchase_title":"Purchase","decisions_purchase":"Car, trim, city, dealer and contact details.","decisions_drive_title":"Test drive","decisions_drive":"The same details, plus a date and time for the visit.","decisions_outcome":"<strong>Takeaway.</strong> The indicator helped people find their place in the multi-step prototype. In the final version, numbered field groups provide that structure. After submission, a separate screen shows the selected car and trim, confirms success with an animation and explains that a manager will get in touch.","decisions_test_link":"Compare the prototypes and results","decisions_final_link":"See both flows in the app","mood_title":"Cars, materials and details.","mood_kicker":"Visual direction","mood_prev":"Previous photo","mood_next":"Next photo","mood_select":"Choose a model","mood_photo_0":"ELANTRA · front view","mood_photo_1":"ELANTRA · interior","mood_photo_2":"ELANTRA · details","mood_photo_3":"SONATA · front view","mood_photo_4":"SONATA · interior","mood_photo_5":"SONATA · details","mood_photo_6":"TUCSON · front view","mood_photo_7":"TUCSON · interior","mood_photo_8":"TUCSON · details","mood_photo_9":"SANTA FE · front view","mood_photo_10":"SANTA FE · interior","mood_photo_11":"SANTA FE · details","role_heading":"My role","project_role_1":"<strong>Research.</strong> Customer interviews, analysis of barriers and contexts of use, two personas and a customer journey map.","project_role_2":"<strong>Product definition.</strong> Formulating hypotheses and success criteria, prioritising requirements, and designing purchase, test-drive and CRM workflows.","project_role_3":"<strong>UX/UI and validation.</strong> Information architecture, wireframes, prototypes, a design system, design review, A/B testing and interface copy testing.","project_role_4":"<strong>Implementation.</strong> User stories, edge cases and acceptance criteria, development of the Swift iOS app and an interactive web version for the portfolio.","cjm_stage":"Journey stage","cjm_action":"Action","cjm_barrier":"Barrier","cjm_response":"Interface response","cjm_1_0":"Discovery","cjm_1_1":"Identify a model of interest.","cjm_1_2":"—","cjm_1_3":"Car photography and key benefits in the catalog.","cjm_2_0":"Car selection","cjm_2_1":"Compare models, prices and trims.","cjm_2_2":"Differences are hard to find quickly.","cjm_2_3":"A catalog and a trim comparison table.","cjm_3_0":"Start booking","cjm_3_1":"Open the form and choose a city and dealer.","cjm_3_2":"The booking button is hard to find on the car details screen.","cjm_3_3":"A visible Book a test drive button. City and dealer selection are part of the form.","cjm_4_0":"Choose a time","cjm_4_1":"Pick a suitable date and time for the visit.","cjm_4_2":"Customers have to discuss timing separately.","cjm_4_3":"Date and time selection is part of the same form. The manager confirms the visit.","cjm_5_0":"Contact details","cjm_5_1":"Review the full name and phone number, and edit them if needed.","cjm_5_2":"Extra fields and repeated entry add effort.","cjm_5_3":"The full name and phone number are filled in from the profile and can be edited on the same screen.","cjm_6_0":"Submit the request","cjm_6_1":"Review the details and submit the request.","cjm_6_2":"Without feedback, it is unclear whether the request was received.","cjm_6_3":"A separate screen confirms submission with an animation, shows the car and trim, and explains that a manager will call.","cjm_7_0":"Confirm the visit","cjm_7_1":"Hear back from the manager and visit the showroom.","cjm_7_2":"It is unclear who is handling the request or where to go.","cjm_7_3":"My Requests shows the status and dealer address, with a link to directions.","cjm_table_hint":"On narrow screens, scroll the table to the right.","priority_sprint1_title":"Sprint 1 · the core request flow.","priority_sprint2_title":"Sprint 2 · form completion and recovery.","priority_backlog_title":"Later · request dashboard.","mood_photo_12":"PALISADE · front view","mood_photo_13":"PALISADE · interior","mood_photo_14":"PALISADE · details","mood_photo_15":"STARIA · front view","mood_photo_16":"STARIA · interior","mood_photo_17":"STARIA · details","validation_final_kicker":"Final version","validation_purchase_detail":"Choose a trim and dealer, with contact details prefilled from the profile.","validation_drive_detail":"Choose the dealer, date and time of the visit in the same form."}},"metadata":{"ru":{"title":"Автосалон Drive&Deal — UX/UI и приложение для iPhone","description":"Исследование, проектирование и реализация Drive&Deal: выбор автомобиля, заявки на покупку и тест-драйв, клиентские статусы и CRM-панель."},"en":{"title":"Drive&Deal Showroom — UX/UI and iPhone app","description":"Research, design and implementation of Drive&Deal: car selection, purchase and test-drive requests, customer statuses and a CRM panel."}}};
  const cjm = document.querySelector('[data-dd-cjm]');
  const cjmImage = cjm.querySelector('img');
  const cjmImages = {
    ru: { src: 'assets/drive-deal-case/cjm.png', width: 7824, height: 4352 },
    en: { src: 'assets/drive-deal-case/cjm-en.png', width: 1681, height: 935 }
  };
  let current = '';
  function apply(value) {
    const language = value === 'en' ? 'en' : 'ru';
    if (current === language) return;
    current = language;
    document.querySelectorAll('[data-dd-copy]').forEach(element => {
      const text = data.copy[language][element.dataset.ddCopy];
      if (text !== undefined) element.innerHTML = text;
    });
    document.querySelectorAll('[data-dd-alt]').forEach(element => {
      element.alt = data.copy[language][element.dataset.ddAlt];
    });
    const map = cjmImages[language];
    cjm.href = map.src;
    cjmImage.width = map.width;
    cjmImage.height = map.height;
    cjmImage.src = map.src;
    document.querySelectorAll('[data-dd-label]').forEach(element => {
      element.setAttribute('aria-label', data.copy[language][element.dataset.ddLabel]);
    });
    document.querySelectorAll('[data-dd-video-label]').forEach(element => {
      element.setAttribute('aria-label', data.copy[language][element.dataset.ddVideoLabel]);
      element.closest('a')?.setAttribute('aria-label', data.copy[language][element.dataset.ddVideoLabel]);
    });
    document.title = data.metadata[language].title;
    document.querySelector('meta[name="description"]').content = data.metadata[language].description;
    document.querySelectorAll('.dd-table-scroll').forEach(element => {
      element.setAttribute('role', 'region');
      element.setAttribute('aria-label', language === 'en' ? 'Data table: scroll horizontally' : 'Таблица: доступна горизонтальная прокрутка');
    });
  }
  window.setLanguage = value => {
    const language = value === 'en' ? 'en' : 'ru';
    if (document.documentElement.lang !== language) document.documentElement.lang = language;
    apply(language);
  };
  new MutationObserver(() => apply(document.documentElement.lang)).observe(document.documentElement, {attributes:true,attributeFilter:['lang']});
  window.addEventListener('message', event => {
    if (event.source !== window && event.source !== window.parent) return;
    if (event.data?.type === 'portfolio-language' && ['ru','en'].includes(event.data.lang)) window.setLanguage(event.data.lang);
  });
  apply(window.__portfolioInitialLanguage || document.documentElement.lang);
})();
